// ***************
// Filename: blur_sharpen_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of blur_sharpen: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to blur_sharpen's logic on named ports, its
//   status comes back on input ports. Blur / sharpen filter pair: mode, frame
//   size, shifts and both kernel banks (taken at a frame start by the
//   filter). Generated by ip/scripts/regmap_gen.py from
//   blur_sharpen_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 9, byte offsets):
//     0x000 ID          RO   "BLSH" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x004 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x008 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x00C reserved    RO   0
//     0x014 MODE        RW   0 blur, 1 sharpen, 2 sharpen then blur, 3 blur
//                       then sharpen, 4-7 pass-through, reset 0x0
//     0x018 FRAME_SIZE  RW   [15:0] width [31:16] height (>= (N+1)/2 each, at
//                       least 14 pixels; must match the frames), reset
//                       {RESET_H, RESET_W}
//     0x01C BLUR_SHIFT  RW   blur normalisation shift, reset
//                       conv2d_pkg::blur_shift(N)
//     0x020 SHARP_SHIFT RW   sharpen normalisation shift, reset
//                       conv2d_pkg::blur_shift(N)
//     0x024 STATUS      RO   [2:0] mode of the last frame that entered
//                       [31:16] frames out
//     0x028 INFO        RO   [3:0] N [11:8] COEF_W [23:16] C [31:24] CW
//     0x050 + 4 i BLUR_K [N * N] RW   blur kernel coefficient i = r*N + c,
//                       signed, reset K_BLUR[i*32 +: 32]
//     0x0D0 + 4 i SHARP_K [N * N] RW   sharpen kernel coefficient i, signed,
//                       reset K_SHARP[i*32 +: 32]
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-21
module blur_sharpen_regs #(
  parameter int N = 5,  // kernel size: 3 or 5
  parameter int COEF_W = 12,  // coefficient width
  parameter logic [15:0] RESET_W = 16'd1920,  // FRAME_SIZE width at reset
  parameter logic [15:0] RESET_H = 16'd1080,  // FRAME_SIZE height at reset
  parameter logic [conv2d_pkg::KMAX*32-1:0] K_BLUR = '0,  // blur kernel at reset (conv2d_pkg::blur_kernel)
  parameter logic [conv2d_pkg::KMAX*32-1:0] K_SHARP = '0  // sharpen kernel at reset (conv2d_pkg::sharpen_kernel)
) (
  input  logic                        clk,              // clock
  input  logic                        rst_n,            // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 9
  axil_if.slave s_axil,
  // r: blur_sharpen_regs_if.regs (src/include/blur_sharpen_regs_if.sv) {mode_o=cfg_mode mode_wr_o=cfg_mode_wr frame_size_o=cfg_frame_size frame_size_wr_o=cfg_frame_size_wr blur_shift_o=cfg_blur_shift blur_shift_wr_o=cfg_blur_shift_wr sharp_shift_o=cfg_sharp_shift sharp_shift_wr_o=cfg_sharp_shift_wr status_i=sts_status info_i=sts_info blur_k_o=cfg_blur_k blur_k_wr_o=cfg_blur_k_wr sharp_k_o=cfg_sharp_k sharp_k_wr_o=cfg_sharp_k_wr}
  blur_sharpen_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [3-1:0] mode_o;
  logic mode_wr_o;
  logic [32-1:0] frame_size_o;
  logic frame_size_wr_o;
  logic [5-1:0] blur_shift_o;
  logic blur_shift_wr_o;
  logic [5-1:0] sharp_shift_o;
  logic sharp_shift_wr_o;
  logic [32-1:0] status_i;
  logic [32-1:0] info_i;
  logic [(N * N)*(COEF_W)-1:0] blur_k_o;
  logic [N * N-1:0] blur_k_wr_o;
  logic [(N * N)*(COEF_W)-1:0] sharp_k_o;
  logic [N * N-1:0] sharp_k_wr_o;
  assign r.cfg_mode = mode_o;
  assign r.cfg_mode_wr = mode_wr_o;
  assign r.cfg_frame_size = frame_size_o;
  assign r.cfg_frame_size_wr = frame_size_wr_o;
  assign r.cfg_blur_shift = blur_shift_o;
  assign r.cfg_blur_shift_wr = blur_shift_wr_o;
  assign r.cfg_sharp_shift = sharp_shift_o;
  assign r.cfg_sharp_shift_wr = sharp_shift_wr_o;
  assign status_i = r.sts_status;
  assign info_i = r.sts_info;
  assign r.cfg_blur_k = blur_k_o;
  assign r.cfg_blur_k_wr = blur_k_wr_o;
  assign r.cfg_sharp_k = sharp_k_o;
  assign r.cfg_sharp_k_wr = sharp_k_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "BLSH";
  localparam logic [31:0] IP_VERSION = "1.00";
  localparam logic [31:0] IP_DATE    = 32'h10112026;   // mm/dd/yyyy, BCD
  localparam logic [8:0] A_ID = 9'h0, A_VERSION = 9'h4, A_DATE = 9'h8;
  localparam logic [8:0] A_MODE = 9'h14;
  localparam logic [8:0] A_FRAME_SIZE = 9'h18;
  localparam logic [8:0] A_BLUR_SHIFT = 9'h1C;
  localparam logic [8:0] A_SHARP_SHIFT = 9'h20;
  localparam logic [8:0] A_STATUS = 9'h24;
  localparam logic [8:0] A_INFO = 9'h28;
  localparam logic [8:0] A_BLUR_K = 9'h50;   // + 4 i, i < N * N
  localparam logic [8:0] A_SHARP_K = 9'hD0;   // + 4 i, i < N * N
  localparam int MAP_WORDS = 77;

  logic             wr_en, rd_en, wr_err_q;
  logic [8:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(9)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(9),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [8:0] wa = {wr_addr[8:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] mode_q;
  logic [31:0] frame_size_q;
  logic [31:0] blur_shift_q;
  logic [31:0] sharp_shift_q;
  logic [31:0] blur_k_q [N * N];
  logic [31:0] sharp_k_q [N * N];
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      mode_q <= 32'h0;
      mode_wr_o <= 1'b0;
      frame_size_q <= 32'({RESET_H, RESET_W});
      frame_size_wr_o <= 1'b0;
      blur_shift_q <= 32'(conv2d_pkg::blur_shift(N));
      blur_shift_wr_o <= 1'b0;
      sharp_shift_q <= 32'(conv2d_pkg::blur_shift(N));
      sharp_shift_wr_o <= 1'b0;
      for (int i = 0; i < N * N; i++) blur_k_q[i] <= 32'(K_BLUR[i*32 +: 32]);
      blur_k_wr_o <= '0;
      for (int i = 0; i < N * N; i++) sharp_k_q[i] <= 32'(K_SHARP[i*32 +: 32]);
      sharp_k_wr_o <= '0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_STATUS || wa == A_INFO);   // writes to read-only words: SLVERR
      begin
        mode_wr_o <= wr_en && wa == A_MODE;
        if (wr_en && wa == A_MODE) mode_q <= (mode_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_size_wr_o <= wr_en && wa == A_FRAME_SIZE;
        if (wr_en && wa == A_FRAME_SIZE) frame_size_q <= (frame_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blur_shift_wr_o <= wr_en && wa == A_BLUR_SHIFT;
        if (wr_en && wa == A_BLUR_SHIFT) blur_shift_q <= (blur_shift_q & ~wmask) | (wr_data & wmask);
      end
      begin
        sharp_shift_wr_o <= wr_en && wa == A_SHARP_SHIFT;
        if (wr_en && wa == A_SHARP_SHIFT) sharp_shift_q <= (sharp_shift_q & ~wmask) | (wr_data & wmask);
      end
      for (int i = 0; i < N * N; i++) begin
        blur_k_wr_o[i] <= wr_en && wa == A_BLUR_K + 9'(4 * i);
        if (wr_en && wa == A_BLUR_K + 9'(4 * i)) blur_k_q[i] <= (blur_k_q[i] & ~wmask) | (wr_data & wmask);
      end
      for (int i = 0; i < N * N; i++) begin
        sharp_k_wr_o[i] <= wr_en && wa == A_SHARP_K + 9'(4 * i);
        if (wr_en && wa == A_SHARP_K + 9'(4 * i)) sharp_k_q[i] <= (sharp_k_q[i] & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign mode_o = mode_q[3-1:0];
  assign frame_size_o = frame_size_q[32-1:0];
  assign blur_shift_o = blur_shift_q[5-1:0];
  assign sharp_shift_o = sharp_shift_q[5-1:0];
  always_comb for (int i = 0; i < N * N; i++) blur_k_o[i*(COEF_W) +: COEF_W] = blur_k_q[i][COEF_W-1:0];
  always_comb for (int i = 0; i < N * N; i++) sharp_k_o[i*(COEF_W) +: COEF_W] = sharp_k_q[i][COEF_W-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[8:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_MODE: rd_data = 32'(mode_q[3-1:0]);
      A_FRAME_SIZE: rd_data = 32'(frame_size_q[32-1:0]);
      A_BLUR_SHIFT: rd_data = 32'(blur_shift_q[5-1:0]);
      A_SHARP_SHIFT: rd_data = 32'(sharp_shift_q[5-1:0]);
      A_STATUS: rd_data = 32'(status_i);
      A_INFO: rd_data = 32'(info_i);
      default: begin
        for (int i = 0; i < N * N; i++)
          if (rd_addr_q == A_BLUR_K + 9'(4 * i)) rd_data = 32'(blur_k_q[i][COEF_W-1:0]);
        for (int i = 0; i < N * N; i++)
          if (rd_addr_q == A_SHARP_K + 9'(4 * i)) rd_data = 32'(sharp_k_q[i][COEF_W-1:0]);
      end
    endcase
  end
endmodule
